"""Tests for tasks module — task-backed calendar event detection."""

from __future__ import annotations

from personal_assistant_dashboard.tasks import is_task_event

# Verbatim description Google puts on a task that has a due date and time.
_TASK_DESC = (
    "Changes made to the title, description, or attachments will not be "
    "saved. To make edits, please go to: "
    "https://tasks.google.com/task/ZOawPUdoteZ6clm-"
)


def test_task_backed_event():
    assert is_task_event({"summary": "DEPLOY AO", "description": _TASK_DESC})


def test_real_focus_time_event():
    """eventType is focusTime for both — only the link separates them."""
    assert not is_task_event(
        {"summary": "Focus", "event_type": "focusTime", "description": "heads down"}
    )


def test_no_description():
    assert not is_task_event({"summary": "Standup"})


def test_unrelated_google_link():
    assert not is_task_event({"description": "https://tasks.google.com/lists/abc"})
